{
  "ruleset_id": "city_stage_grant",
  "rules": [
    {
      "description": "Project leader must be an adult.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "team.project_lead_age",
        "op": "ge",
        "value": 18
      }
