      "description": "Consent from venue required for on-site events.",
      "severity": "critical",
      "category": "event",
      "condition": {
        "field": "documents.venue_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The requested grant amount cannot exceed 1,500,000 rubles.",
      "severity": "critical",
      "category": "budget",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 1500000
      }
    }
  ]
}

{
  "ruleset_id": "additional_education_policy",
  "rules": [
    {
      "description": "Programme has valid education license",
      "severity": "critical",
      "category": "license",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Total hours of program must be at least 72",
      "severity": "critical",
      "category": "hours",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "At least 80% of teachers must have relevant qualifications",
      "severity": "critical",
      "category": "qualifications",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "Delivery format must be either 'face-to-face' or 'blended'",
      "severity": "critical",
      "category": "format",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": ["очно", "смешанно"]
      }
    }
  ]
}

{
  "ruleset_id": "subsidy_energy_efficiency",
  "rules": [
    {
      "description": "Energy consumption reduction must be at least 20%",
      "severity": "critical",
      "category": "energy",
      "condition": {
        "field": "project.energy_consumption_reduction_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Co-financing percentage must be at least 30%",
      "severity": "critical",
      "category": "finance",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 30
      }
    },
    {
      "description": "Technical passport must be provided",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.technical_passport.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Project completion must be on or before December 31, 2027",
      "severity": "critical",
      "category": "schedule",
      "condition": {
        "field": "project.completion_date",
        "op": "le",
        "value": "2027-12-31"
      }
    }
  ]
}

{
  "ruleset_id": "norstar_main_trek_policy",
  "rules": [
    {
      "description": "Organization must be registered for at least 24 months to apply for main track grant; exceptions exist for organizations younger than 24 months applying to Accelerator track.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "org_v2.months_registered",
        "op": "ge",
        "value": 24
      }
    },
    {
      "description": "Grant request amount cannot exceed 250,000 euros for main track grant.",
      "severity": "critical",
      "category": "budget",
      "condition": {
        "field": "org_v2.total_requested",
        "op": "le",
        "value": 250000
      }
    },
    {
      "description": "Independent audit report required for main track application; applications without audit report are rejected.",
      "severity": "critical",
      "category": "documentation",
      "condition": {
        "field": "documents.audit_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Application deadline for cycle 2027 is March 31, 2027 inclusive.",
      "severity": "critical",
      "category": "timeline",
      "condition": {
        "field": "org_v2.submission_date",
        "op": "before",
        "value": "2027-04-01"
      }
    },
    {
      "description": "Headcount declared in application must match headcount reported in annual report.",
      "severity": "critical",
      "category": "consistency",
      "condition": {
        "field": "annual_report.headcount",
        "op": "eq",
        "value": "org_v2.declared_headcount"
      }
    },
    {
      "description": "Annual report must be prepared according to IFRS standards; non-compliance considered as formal deficiency.",
      "severity": "major",
      "category": "reporting",
      "condition": {
        "field": "annual_report.ifrs",
        "op": "eq",
        "value": true
      }
    }
  ]
}

