{
  "ruleset_id": "medical_devices_purchase",
  "rules": [
    {
      "description": "Registration certificate must be present",
      "severity": "critical",
      "category": "registration",
      "condition": {
        "field": "documents.medical_registration.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Remaining shelf life must be at least 12 months",
      "severity": "critical",
      "category": "shelf_life",
      "condition": {
        "field": "product.expiry_months",
        "op": "ge",
        "value": 12
